//go:embed welcome_color.txt
var welcomeColor string
//go:embed version.txt
var versionText string

func isTTY(f *os.File) bool {
	// Use Stat mode check + syscall ioctl for proper isatty
	// First check ModeCharDevice
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	if fi.Mode()&os.ModeCharDevice == 0 {
		return false
	}
	// Use ioctl TCGETS to confirm tty (not /dev/null etc)
	return isattySyscall(int(f.Fd()))
}

func useColor() bool {
	if !isTTY(os.Stdout) {
		return false
	}
	term, ok := os.LookupEnv("TERM")
	if !ok || term == "" || term == "dumb" {
		return false
	}
	if _, ok := os.LookupEnv("NO_COLOR"); ok {
		return false
	}
	return true
}

func printHelp() {
	if useColor() {
		fmt.Fprint(os.Stdout, helpColor)
	} else {
		fmt.Fprint(os.Stdout, helpPlain)
	}
}

func printWelcome() {
	if useColor() {
		fmt.Fprint(os.Stdout, welcomeColor)
	} else {
		fmt.Fprint(os.Stdout, welcomePlain)
	}
}

func printVersion() {
	fmt.Fprint(os.Stdout, versionText)
}

