func parseSingleRange(fieldPart, raw string) (Bound, string) {
	// Check for :
	if strings.Contains(fieldPart, ":") {
		// Split on first :
		idx := strings.Index(fieldPart, ":")
		left := fieldPart[:idx]
		right := fieldPart[idx+1:]
