		if left == "" && right == "" {
			return Bound{}, fmt.Sprintf("failed to parse '%s': Field format error, no numbers next to `:`\n", raw)
		}
		var start, end int
		var hasStart, hasEnd bool
		var isOpen bool
		if left == "" {
			// :2 => start defaults to 1
			start = 1
			hasStart = false // missing, defaults
