				} else {
					return Bound{}, fmt.Sprintf("failed to parse '%s': Not a number `%s`\n", raw, left)
				}
			}
			start = v
			hasStart = true
		}
		if right == "" {
			// 1: => open
			isOpen = true
			hasEnd = false
			end = 0
		} else {
			v, err := parseIntStrict(right)
