		// For -1:-2 (both negative, -1 > -2) => error.
		// For mixed signs (e.g., 2:-5, -1:1), do NOT check at parse (defer to runtime).
		// How to detect mixed? If (start>0 and end<0) or (start<0 and end>0) => mixed, skip check.
		// What about start=1 (from :2, missing) and end=-1 (e.g., :-1? Start 1, end -1, mixed, skip? Probably.
		if !isOpen {
			// both start and end defined (start may be default 1 for :2)
			// Check if same sign (both >0 or both <0) and start > end => parse error
			if (start > 0 && end > 0 && start > end) || (start < 0 && end < 0 && start > end) {
				return Bound{}, fmt.Sprintf("failed to parse '%s': Field left value cannot be greater than right value\n", raw)
