			}
			if hasFB {
				b.Fallback = fb
				b.HasFallback = true
			}
			b.Raw = fieldPart
			// Flush literal before field
			if curLiteral.Len() > 0 {
				parts = append(parts, FormatPart{IsField: false, Literal: curLiteral.String()})
				curLiteral.Reset()
			}
			parts = append(parts, FormatPart{IsField: true, Bound: b})
			boundsCount++
			i = closing + 1
			continue
		}
		if s[i] == '}' {
			// Lone } (not part of }} since we already checked }} above)
			return nil, fmt.Sprintf("failed to parse '%s': Field format error: missing opening parenthesis\n", raw)
		}
		// Literal char
		curLiteral.WriteByte(s[i])
		i++
	}
