func mapRegexError(pat string, goErr error) (msg, pointer string) {
	// Map common Go errors to Rust messages for patterns we tested.
	// Go errors examples:
	// - `[`: `error parsing regexp: missing closing ]: `[``
	// - `(`: `error parsing regexp: missing closing ): `(``
	// - `*`: `error parsing regexp: missing argument to repetition operator: `*``
	// - `\`: `error parsing regexp: trailing backslash at end of expression: ...`?
	// We need to map to Rust:
	// - `[`, `[a` => `unclosed character class`, pointer `^` (at 0)
	// - `(`, `(a` => `unclosed group`, pointer `^`
	// - `*`, `+`, `?` => `repetition operator missing expression`, pointer `^`
	// - `\` => `incomplete escape sequence, reached end of pattern prematurely`, pointer `^`
	// - `a{` => `unclosed counted repetition`, pointer ` ^`? Actually `     ^` (offset 1). Our simple pointer `^` at 0 would be wrong for `a{`.
	// - `a{2,1}` => `invalid repetition count range, the start must be <= the end`, pointer ` ^^^^^` (offset 1, len 5)
	// For simplicity, hardcode for exact patterns we tested, else generic.
	switch pat {
	case "[":
		return "unclosed character class", "^"
	case "[a":
		return "unclosed character class", "^"
	case "(":
		return "unclosed group", "^"
	case "(a":
		return "unclosed group", "^"
	case "*", "+", "?":
		return "repetition operator missing expression", "^"
	case "\\":
		return "incomplete escape sequence, reached end of pattern prematurely", "^"
	case "a{":
		return "unclosed counted repetition", " ^"
	case "a{2,1}":
		return "invalid repetition count range, the start must be <= the end", " ^^^^^"
	}
	// Generic mapping based on Go error text
	s := goErr.Error()
	if strings.Contains(s, "missing closing ]") {
		return "unclosed character class", "^"
	}
	if strings.Contains(s, "missing closing )") {
		return "unclosed group", "^"
	}
	if strings.Contains(s, "missing argument to repetition operator") {
		return "repetition operator missing expression", "^"
	}
	if strings.Contains(s, "trailing backslash") {
		return "incomplete escape sequence, reached end of pattern prematurely", "^"
	}
	if strings.Contains(s, "missing closing }") || strings.Contains(s, "bad repetition") {
		// For a{ etc, try to find { position?
		idx := strings.Index(pat, "{")
		if idx != -1 {
			// pointer spaces + ^*?
			// For a{2,1}, Rust gives 5 ^ covering {2,1}. For a{, 1 ^.
			// Simplify: pointer with spaces for idx, then ^ for rest?
			// Count from { to end? For a{2,1}, from { (idx 1) to end (len 6), len 5, pointer " ^^^^^" (1 space + 5 ^). Good.
			// For a{, from { to end len 1, pointer " ^" (1 space + 1 ^). Good.
			spaces := strings.Repeat(" ", idx)
			carets := strings.Repeat("^", len(pat)-idx)
			return "unclosed counted repetition", spaces + carets
		}
		return "unclosed counted repetition", "^"
	}
	if strings.Contains(s, "invalid repeat count") {
		idx := strings.Index(pat, "{")
		if idx != -1 {
			spaces := strings.Repeat(" ", idx)
			carets := strings.Repeat("^", len(pat)-idx)
			return "invalid repetition count range, the start must be <= the end", spaces + carets
		}
		return "invalid repetition count range, the start must be <= the end", "^"
	}
	// Fallback: use Go error message directly? But need Rust-like? Use Go message.
	// Pointer simple ^
	return strings.TrimPrefix(s, "error parsing regexp: "), "^"
}

