	var out strings.Builder
	out.WriteByte('"')
	for _, c := range b {
		switch c {
		case '"':
			out.WriteString("\\\"")
		case '\\':
			out.WriteString("\\\\")
		case '\b': // 0x08
			out.WriteString("\\b")
		case '\f': // 0x0C
			out.WriteString("\\f")
		case '\n':
			out.WriteString("\\n")
		case '\r':
			out.WriteString("\\r")
		case '\t':
			out.WriteString("\\t")
		default:
			if c < 0x20 {
				// \u00XX lowercase
				out.WriteString(fmt.Sprintf("\\u%04x", c))
			} else {
				out.WriteByte(c)
			}
		}
	}
	out.WriteByte('"')
	return out.String()
}

